    const days = hours / 24
    const weeks = days / 7
    const months = days / (365 / 12)
    const years = days / 365

    if (this.locale === JAPANESE_LOCALE) {
      if (years >= 1) return `${Math.floor(years)}年前`
      if (months >= 1) return `${Math.floor(months)}か月前`
      if (weeks >= 1) return `${Math.floor(weeks)}週間前`
      if (days >= 1) return `${Math.floor(days)}日前`
      if (hours >= 1) return `${Math.floor(hours)}時間前`
      if (minutes >= 1) return `${Math.floor(minutes)}分前`
      return "1分未満前"
